package ch.bbw.zork;import java.util.Arrays;import java.util.List;public class CommandWords {	private List<String> validCommands = Arrays.asList(			"continue",			"return",			"look",			"status",			"search",			"inventory",			"flashlight",			"shop",			"buy",			"use",			"hide",			"unhide",			"peek",			"bandage",			"battery",			"quit",			"help"	);	public boolean isCommand(String commandWord) {		return validCommands.contains(commandWord);	}	public String showAll() {		return String.join(" ", validCommands);	}}